import{_ as e,c as t,o as a,f as i}from"./chunks/framework.BOAZPCR7.js";const f=JSON.parse('{"title":"Defining the molecular interaction between influenza hemagglutinin and MHC-II","description":"","frontmatter":{"layout":"paper","title":"Defining the molecular interaction between influenza hemagglutinin and MHC-II","date":"2026-07-23","authors":["Bernadeta Dadonaite","Annie Dosey","Jenny J Ahn","Timothy C Yu","Sara A Sunshine","Ariana G Farrell","Neil P King","Jesse D Bloom"],"journal":"bioRxiv","doi":"10.64898/2026.07.17.738765","link":"https://doi.org/10.64898/2026.07.17.738765","image":"/assets/papers/2026_dadonaite.png","keywords":["Influenza","Deep mutational scanning","Pseudovirus"],"selected":true,"head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/papers/2026_dadonaite.html"}]]},"headers":[],"relativePath":"papers/2026_dadonaite.md","filePath":"papers/2026_dadonaite.md"}'),n={name:"papers/2026_dadonaite.md"},o=i('<h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The hemagglutinin (HA) of some influenza viruses can interact with major histocompatibility complex class II (MHC-II), but how these proteins interact is unclear. Here we demonstrate that diverse H5 HAs can use MHC-II to enter cells, with avian MHC-II enabling more efficient entry than human MHC-II for most H5 HAs. To define the molecular interface, we use pseudovirus deep mutational scanning to measure how mutations to H5 HA affect its interaction with tufted duck MHC-II, and identify mutations that restrict HA to exclusively MHC-II or sialic acid receptors. We leverage identification of H5 HA mutations that increase binding to tufted duck MHC-II to determine a 4.8 Å cryo-EM model of the complex. To support the structural model, we measure how all mutations to tufted duck MHC-II affect its interaction with H5 HA, and find the alpha chain is the dominant determinant but beta chain sites near the peptide-binding groove also contribute. To generalize these findings, we use deep mutational scanning to show that a H7 HA interacts with MHC-II similarly to H5 HA. Finally, we show that H1, H2, H3, and H9 HAs interact with avian or human MHC-II, although interactions vary among strains that evolved in different hosts.</p><h2 id="interactive-visualizations" tabindex="-1">Interactive visualizations <a class="header-anchor" href="#interactive-visualizations" aria-label="Permalink to &quot;Interactive visualizations&quot;">​</a></h2><p>The results described in this paper can be interactively visualized at <a href="https://dms-vep.org/Flu-H5N1-American-Wigeon-2021-HA-tufted-duck-MHCII-DMS/" target="_blank" rel="noreferrer">https://dms-vep.org/Flu-H5N1-American-Wigeon-2021-HA-tufted-duck-MHCII-DMS/</a>.</p>',4),r=[o];function s(l,c,d,h,u,m){return a(),t("div",null,r)}const H=e(n,[["render",s]]);export{f as __pageData,H as default};
